14	import java.util.Collection;
15	import java.util.List;
16	import java.util.Map;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region lookup used to derive an owner's locality. */
25	    Map<String, String> CITY_REGION = Map.of(
26	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Fills the presentation-only {@code displayName} as {@code "LastName, FirstName"}
32	     * from the stored names, once MapStruct has mapped the remaining fields.
33	     */
34	    @AfterMapping
35	    default void addDisplayName(Owner owner, @MappingTarget OwnerDto ownerDto) {
36	        ownerDto.setDisplayName(owner.getLastName() + ", " + owner.getFirstName());
37	    }
38	
39	    /**
40	     * Fills the presentation-only {@code initials} as the upper-cased first letters of
41	     * firstName and lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
42	     */
43	    @AfterMapping
44	    default void addInitials(Owner owner, @MappingTarget OwnerDto ownerDto) {
45	        ownerDto.setInitials(
46	            Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
47	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".");
48	    }
49	
50	    /**
51	     * Fills the presentation-only {@code membershipNumber} as {@code '<customerCode>-M<YY>'}
52	     * where YY is the last two digits of the registrationDate year. Left null when either
53	     * source field is missing.
54	     */
55	    @AfterMapping
56	    default void addMembershipNumber(Owner owner, @MappingTarget OwnerDto ownerDto) {
57	        if (owner.getCustomerCode() != null && owner.getRegistrationDate() != null) {
58	            String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
59	            ownerDto.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
60	        }
61	    }
62	
63	    /**
64	     * Fills the presentation-only {@code membershipTier}: {@code 'SILVER'} when
65	     * namesakeCount is 0 and an email is present, otherwise {@code 'BRONZE'}.
66	     */
67	    @AfterMapping
68	    default void addMembershipTier(Owner owner, @MappingTarget OwnerDto ownerDto) {
69	        boolean silver = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0
70	            && owner.getEmail() != null && !owner.getEmail().isEmpty();
71	        ownerDto.setMembershipTier(silver ? "SILVER" : "BRONZE");
72	    }
73	
74	    /**
75	     * Fills the presentation-only {@code locality} as the canonical region derived from
76	     * the owner's city via the fixed {@link #CITY_REGION} table, or {@code 'UNKNOWN'}
77	     * when the city is not in the table.
78	     */
79	    @AfterMapping
80	    default void addLocality(Owner owner, @MappingTarget OwnerDto ownerDto) {
81	        ownerDto.setLocality(CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN"));
82	    }
83	
84	    Owner toOwner(OwnerDto ownerDto);
85	
86	    @Mapping(target = "id", ignore = true)
87	    @Mapping(target = "pets", ignore = true)
88	    Owner toOwner(OwnerFieldsDto ownerDto);
89	
90	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
91	
92	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
93	
94	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
95	        OwnerPageDto ownerPageDto = new OwnerPageDto();
96	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
97	        ownerPageDto.setPage(ownerPage.getNumber());
98	        ownerPageDto.setSize(ownerPage.getSize());
99	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
100	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
101	        return ownerPageDto;
102	    }
103	}
