272	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
273	     * one more than the number of owners already in that city.
274	     */
275	    private String generateCustomerCode(Owner owner) {
276	        String cityPrefix = prefix3(owner.getCity());
277	        String lastNamePrefix = prefix3(owner.getLastName());
278	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
279	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
