345	    private long countOwnersInCity(String city) {
346	        String normalized = normalizeHouseholdValue(city);
347	        return ownerRepository.findAll().stream()
348	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
349	                .count();
350	    }
351	
352	    /**
353	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
354	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
355	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
356	     * that already existed before this create.
357	     */
358	    private int countNamesakes(Owner owner) {
359	        String firstName = normalizeHouseholdValue(owner.getFirstName());
360	        String lastName = normalizeHouseholdValue(owner.getLastName());
361	        int count = 0;
362	        for (Owner existing : ownerRepository.findAll()) {
363	            if (!existing.getId().equals(owner.getId())
364	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
365	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
366	                count++;
367	            }
368	        }
369	        return count;
370	    }
371	
372	    private static String normalizeEmail(String email) {
373	        return email == null ? null : email.toLowerCase(Locale.ROOT);
374	    }
375	
376	    /** Common street-type abbreviations expanded during address normalization. */
377	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
378	        "ST", "STREET",
379	        "RD", "ROAD",
380	        "AVE", "AVENUE");
381	
382	    /**
383	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
384	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
385	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
386	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
387	     * form.
388	     */
389	    private static String normalizeAddress(String address) {
390	        if (address == null) {
391	            return null;
392	        }
393	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
394	        if (collapsed.isEmpty()) {
395	            return "";
396	        }
397	        String[] tokens = collapsed.split(" ");
398	        StringBuilder sb = new StringBuilder(collapsed.length());
399	        for (int i = 0; i < tokens.length; i++) {
400	            if (i > 0) {
401	                sb.append(' ');
402	            }
403	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
404	        }
405	        return sb.toString();
406	    }
