36	    /**
37	     * Convert a raw telephone number to E.164 form, or return {@code null} if it cannot
38	     * form a valid E.164 number.
39	     *
40	     * @param raw the raw telephone number as supplied by the client (may be {@code null})
41	     * @return the normalized {@code +<digits>} string, or {@code null} when invalid
42	     */
43	    public static String toE164(String raw) {
44	        if (raw == null) {
45	            return null;
46	        }
47	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
48	        String digits;
49	        if (cleaned.startsWith("+")) {
50	            String body = cleaned.substring(1);
51	            if (!body.matches("\\d+")) {
52	                return null;
53	            }
54	            digits = body;
55	        }
56	        else {
57	            if (!cleaned.matches("\\d+")) {
58	                return null;
59	            }
